package scp_candidate.Mining_Cargo_Transfer_Supervisor

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait TransferCommandDerivation_Api {
  def id: Art.BridgeId
  def resolution_Id : Art.PortId
  def command_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var command: Mining_Cargo_Transfer_Supervisor.CargoTransferCommand.Type = $

  def put_command(value : Mining_Cargo_Transfer_Supervisor.CargoTransferCommand.Type) : Unit = {
    Contract(
      Modifies(command),
      Ensures(
        command == value
      )
    )
    Spec {
      command = value
    }

    Art.putValue(command_Id, Mining_Cargo_Transfer_Supervisor.CargoTransferCommand_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class TransferCommandDerivation_Initialization_Api (
  val id: Art.BridgeId,
  val resolution_Id : Art.PortId,
  val command_Id : Art.PortId) extends TransferCommandDerivation_Api

@datatype class TransferCommandDerivation_Operational_Api (
  val id: Art.BridgeId,
  val resolution_Id : Art.PortId,
  val command_Id : Art.PortId) extends TransferCommandDerivation_Api {

  // Logika spec var representing port state for incoming data port
  @spec var resolution: Mining_Cargo_Transfer_Supervisor.TransferResolution = $

  def get_resolution() : Option[Mining_Cargo_Transfer_Supervisor.TransferResolution] = {
    Contract(
      Ensures(
        Res == Some(resolution)
      )
    )
    val value : Option[Mining_Cargo_Transfer_Supervisor.TransferResolution] = Art.getValue(resolution_Id) match {
      case Some(Mining_Cargo_Transfer_Supervisor.TransferResolution_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port resolution.  Expecting 'Mining_Cargo_Transfer_Supervisor.TransferResolution_Payload' but received ${v}")
        None[Mining_Cargo_Transfer_Supervisor.TransferResolution]()
      case _ => None[Mining_Cargo_Transfer_Supervisor.TransferResolution]()
    }
    return value
  }
}
